document.addEventListener("nav",()=>{for(let e of document.querySelectorAll(".page-footer .backlinks li > a")){if(e.nextElementSibling?.classList.contains("backlink-path"))continue;let t=e.getAttribute("href")??"";try{t=decodeURIComponent(t)}catch{}let c=t.replace(/[?#].*$/,"").replace(/^(\.\.?\/)+/,"").split("/").slice(0,-1);if(!c.length)continue;let n=document.createElement("span");n.className="backlink-path",n.textContent=c.join(" / "),e.after(n)}});
